  const STORAGE_KEY = 'mifeco_discovered_leads';

  function getLeads() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
    catch { return []; }
  }

  function saveLeads(leads) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(leads));
  }

  function renderLeads() {
    const leads = getLeads();
    const container = document.getElementById('leads-list');
    const countEl = document.getElementById('lead-count');
    countEl.textContent = leads.length;

    if (leads.length === 0) {
      container.innerHTML = `
        <div class="empty-state">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#64748b" stroke-width="1.5">
