          </svg>
          <p>No leads discovered yet. Start searching on LinkedIn and save your findings above.</p>
        </div>`;
      return;
    }

    container.innerHTML = leads.map((lead, i) => `
      <div class="lead-item">
        <div class="info">
          <div class="name">${escapeHtml(lead.name)}</div>
          <div class="meta">
            <span class="title">${escapeHtml(lead.title)}</span> · ${escapeHtml(lead.company)}
            ${lead.has_email ? '<span class="email-badge">✉️ Has Email</span>' : ''}
            ${lead.url ? `<a href="${escapeHtml(lead.url)}" target="_blank" class="linkedin-link">🔗 Profile</a>` : ''}
          </div>
          ${lead.notes ? `<div class="notes-preview">${escapeHtml(lead.notes.substring(0,120))}${lead.notes.length > 120 ? '…' : ''}</div>` : ''}
        </div>
        <div class="actions">
          <button class="btn btn-danger btn-sm" onclick="deleteLead(${i})">Delete</button>
        </div>
      </div>
    `).join('');
  }

  function addLead() {
    const name = document.getElementById('lead-name').value.trim();
    const title = document.getElementById('lead-title').value.trim();
    const company = document.getElementById('lead-company').value.trim();
    const url = document.getElementById('lead-url').value.trim();
    const has_email = document.getElementById('lead-email').checked;
    const notes = document.getElementById('lead-notes').value.trim();

    if (!name || !title || !company) {
      showToast('Please fill in Name, Title, and Company.', 'error');
      return;
    }

    const leads = getLeads();
    // Check duplicate by URL or name+company
    const duplicate = leads.some(l => 
      (url && l.url === url) || 
      (l.name.toLowerCase() === name.toLowerCase() && l.company.toLowerCase() === company.toLowerCase())
    );
    if (duplicate) {
      showToast('This lead already exists (same name+company or URL).', 'error');
      return;
    }

    leads.push({ name, title, company, url, has_email, notes, created_at: new Date().toISOString() });
    saveLeads(leads);
    renderLeads();
    clearForm();
    showToast(`✅ ${name} saved as a lead.`, 'success');
  }

  function deleteLead(index) {
    const leads = getLeads();
    const removed = leads[index].name;
    leads.splice(index, 1);
    saveLeads(leads);
    renderLeads();
    showToast(`🗑️ ${removed} removed.`, 'success');
  }

  function clearAllLeads() {
    if (!confirm('Are you sure you want to delete ALL leads?')) return;
    saveLeads([]);
    renderLeads();
    showToast('All leads cleared.', 'success');
  }

  function clearForm() {
    document.getElementById('lead-name').value = '';
    document.getElementById('lead-title').value = '';
    document.getElementById('lead-company').value = '';
    document.getElementById('lead-url').value = '';
    document.getElementById('lead-email').checked = false;
    document.getElementById('lead-notes').value = '';
  }

  function exportLeads() {
    const leads = getLeads();
    if (leads.length === 0) {
      showToast('No leads to export.', 'error');
      return;
    }
    const blob = new Blob([JSON.stringify(leads, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `mifeco-leads-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(a.href);
    showToast(`📥 Exported ${leads.length} leads as JSON.`, 'success');
  }

  function escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  function showToast(msg, type) {
    const el = document.getElementById('toast');
    el.textContent = msg;
    el.className = 'toast ' + (type || '');
    el.classList.add('show');
    clearTimeout(el._timeout);
    el._timeout = setTimeout(() => el.classList.remove('show'), 3000);
  }

  // Copy note templates
  document.addEventListener('DOMContentLoaded', () => {
    renderLeads();
    document.querySelectorAll('.copy-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        const key = this.dataset.note;
        const textEl = document.getElementById('note-' + key);
        if (!textEl) return;
        let text = textEl.textContent.trim();
        // Replace {{name}} and {{company}} with blanks for user to fill
        text = text.replace(/\{\{name\}\}/g, '_____').replace(/\{\{company\}\}/g, '_____');
        navigator.clipboard.writeText(text).then(() => {
          this.textContent = 'Copied!';
          this.classList.add('copied');
          setTimeout(() => {
            this.textContent = 'Copy';
            this.classList.remove('copied');
          }, 2000);
        }).catch(() => {
          // Fallback
          const textarea = document.createElement('textarea');
          textarea.value = text;
          document.body.appendChild(textarea);
          textarea.select();
          document.execCommand('copy');
          textarea.remove();
          this.textContent = 'Copied!';
          this.classList.add('copied');
          setTimeout(() => {
            this.textContent = 'Copy';
            this.classList.remove('copied');
          }, 2000);
        });
      });
    });
  });
</script>
</body>
</html>
